function countSubarrays(nums) {
  // Build every subarray, keep those of length 3, and test the rule with real division.
  let count = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start + 1; end <= nums.length; end++) {
      const piece = nums.slice(start, end);
      if (piece.length === 3 && piece[0] + piece[2] === piece[1] / 2) count++;
    }
  }
  return count;
}

