  // Plant a few matching windows: outer values in [-25, 25] keep twice their sum within [-100, 100].
  const plants = Math.floor(rand() * (n / 3 + 1));
  for (let p = 0; p < plants; p++) {
    const i = Math.floor(rand() * (n - 2));
    const first = Math.floor(rand() * 51) - 25;
    const third = Math.floor(rand() * 51) - 25;
    nums[i] = first;
    nums[i + 1] = 2 * (first + third);
    nums[i + 2] = third;
  }
  return [nums];
}
